@pytest.mark.integration
def test_read_missing_declared_column_raises_naming_contact_for_external_source(
    spark: SparkSession,
) -> None:
    """A missing declared column is fatal; an external source's message names its contact."""
    from payroll_pipeline.pipeline.read import read

    table = "integration_test.read_drift_missing_external"
    _seed(spark, table, [("a", "2024-01-01")])
    source = _source(
        "events",
        table,
        partition_column=None,
        allow_empty=False,
        columns=("id:string", "event_date:date", "status:string"),
        contact="crm-team@example.com",
    )

    with pytest.raises(ValueError) as exc_info:
        read(spark, "2024-01-01", "2024-01-02", (source,))

    message = str(exc_info.value)
    assert "status" in message
    assert "crm-team@example.com" in message


@pytest.mark.integration
def test_read_missing_declared_column_raises_naming_regenerate_job_for_owned_source(
    spark: SparkSession,
) -> None:
    """An owned source's drift message points at re-running `generate create-job`."""
    from payroll_pipeline.pipeline.read import read

    table = "integration_test.read_drift_missing_owned"
    _seed(spark, table, [("a", "2024-01-01")])
    source = _source(
        "events",
        table,
        partition_column=None,
        allow_empty=False,
        columns=("id:string", "event_date:date", "status:string"),
        layer="processed",
        dataset="clean_orders",
    )

    with pytest.raises(ValueError) as exc_info:
        read(spark, "2024-01-01", "2024-01-02", (source,))

    message = str(exc_info.value)
    assert "status" in message
    assert "generate create-job clean_orders" in message


@pytest.mark.integration
def test_read_retyped_declared_column_raises(spark: SparkSession) -> None:
    """A declared column present with the wrong observed type is fatal, same as missing."""
    from payroll_pipeline.pipeline.read import read

    table = "integration_test.read_drift_retyped"
    _seed(spark, table, [("a", "2024-01-01")])
    # event_date is really `date`, declared here as `string` -- a type mismatch.
    source = _source(
        "events",
        table,
        partition_column=None,
        allow_empty=False,
        columns=("id:string", "event_date:string"),
    )

    with pytest.raises(ValueError) as exc_info:
        read(spark, "2024-01-01", "2024-01-02", (source,))

    assert "event_date" in str(exc_info.value)


